async function processOrder(req: any) {
  const data = JSON.parse(req.body);
  if (!data) throw new Error('bad');
  logger.info('processing', data);
  const validated = validateOrder(data);
  const saved = await db.save(validated);
  notifyWarehouse(saved);
  return { id: saved.id };
}

function generateUserReport(userId: string, options: any) {
  const user = db.find(userId);
  if (options.includeFormat) formatUser(user, options.format);
  if (options.includeHistory) user.history = loadHistory(userId);
  if (options.exportCSV) writeCsv(user);
  if (options.includeSensitive && !authorized()) throw new Error('unauthorized');
  return buildReport(user);
}

